int fn0(List<int> packetSizes, int minBandwidth) {
  int target = minBandwidth * 2;
  int low = 0, high = packetSizes.length - 1;
  while (low <= high) {
    int mid = low + (high - low) ~/ 2;
    if (packetSizes[mid] < target) low = mid + 1;
    else high = mid - 1;
  }
  return low;
}

