bool fn0(int batchId, int storageBase) {
  if (batchId <= 0 || storageBase < 2 || storageBase > 16) {
    return false;
  }
  int temp = batchId;
  int digitSum = 0;
  while (temp > 0) {
    digitSum += temp % storageBase;
    temp ~/= storageBase;
  }
  if (digitSum == 0 || batchId % digitSum != 0) {
    return false;
  }
  int a = digitSum;
  int b = storageBase;
  while (b != 0) {
    int t = b;
    b = a % b;
    a = t;
  }
  return a == 1;
}

