List<int> fn0(List<String> strands) {
  if (strands.isEmpty) return [0, -1];
  var q = strands[0];
  int l = 1, r = strands.length;
  while (l < r) {
    var m = (l + r) >> 1;
    if (strands[m].compareTo(q) < 0) l = m + 1; else r = m;
  }
  int s = l;
  r = strands.length;
  while (l < r) {
    var m = (l + r) >> 1;
    if (strands[m].compareTo('$q[') < 0) l = m + 1; else r = m;
  }
  return [s, l - 1];
}

