int fn0(int pattern) {
  int masked = pattern & 0x7F;
  int count = 0;
  for (int v = masked; v != 0; v &= v - 1) {
    count++;
  }
  int shift = count % 7;
  return ((masked << shift) | (masked >> (7 - shift))) & 0x7F;
}

