import 'dart:math';

@pragma('vm:never-inline')
@pragma('vm:entry-point')

void fn0() {
  final random = Random(0);

  const int samples = 1000000;       
  const double a = 0.0;              
  const double b = pi;               

  double f(double x) => sin(x);

  double sum = 0.0;
  for (int i = 0; i < samples; i++) {
    double x = a + random.nextDouble() * (b - a);
    sum += f(x);
  }

  double integralEstimate = (b - a) * sum / samples;

  print('Estimating ∫ₐᵇ sin(x) dx with $samples samples:');
  print('  Interval: [$a, $b]');
  print('  Estimated integral = $integralEstimate');
  print('  Exact value        = 2.0');
}

