String fn0(List<int> occupied, int k) {

  int totalEmpty = 64 - occupied.length;
  if (k < 1 || k > totalEmpty) return 'none';
  int lo = 1;
  int hi = 64;
  while (lo < hi) {
    int mid = (lo + hi) ~/ 2;

    int a = 0;
    int b = occupied.length;
    while (a < b) {
      int m = (a + b) ~/ 2;
      if (occupied[m] <= mid) {
        a = m + 1;
      } else {
        b = m;
      }
    }
    int emptiesUpToMid = mid - a;
    if (emptiesUpToMid >= k) {
      hi = mid;
    } else {
      lo = mid + 1;
    }
  }
  String file = String.fromCharCode(97 + (lo - 1) % 8);
  int rank = (lo - 1) ~/ 8 + 1;
  return '$file$rank';
}

