  int leftShift2 = num << 2; 
  int leftShift3 = num << 3; 
  print('\nLeft shift operations:');
  print('$num << 1 = $leftShift1 (binary: ${leftShift1.toRadixString(2).padLeft(8, '0')})');
  print('$num << 2 = $leftShift2 (binary: ${leftShift2.toRadixString(2).padLeft(8, '0')})');
  print('$num << 3 = $leftShift3 (binary: ${leftShift3.toRadixString(2).padLeft(8, '0')})');

  int rightShift1 = num >> 1; 
  int rightShift2 = num >> 2; 
  int rightShift3 = num >> 3; 
  print('\nRight shift operations:');
  print('$num >> 1 = $rightShift1 (binary: ${rightShift1.toRadixString(2).padLeft(8, '0')})');
  print('$num >> 2 = $rightShift2 (binary: ${rightShift2.toRadixString(2).padLeft(8, '0')})');
  print('$num >> 3 = $rightShift3 (binary: ${rightShift3.toRadixString(2).padLeft(8, '0')})');

  int a = 60;  
  int b = 13;  
  print('\nBitwise operations:');
  print('a = $a (binary: ${a.toRadixString(2).padLeft(8, '0')})');
  print('b = $b (binary: ${b.toRadixString(2).padLeft(8, '0')})');
  print('a & b = ${a & b} (binary: ${(a & b).toRadixString(2).padLeft(8, '0')})');
  print('a | b = ${a | b} (binary: ${(a | b).toRadixString(2).padLeft(8, '0')})');
  print('a ^ b = ${a ^ b} (binary: ${(a ^ b).toRadixString(2).padLeft(8, '0')})');
  print('~a = ${~a} (binary: ${(~a).toRadixString(2)})');

  print('\nCheck if power of 2:');
  for (int i = 0; i <= 17; i++) {
    bool isPowerOf2 = (i != 0) && ((i & (i - 1)) == 0);
    if (isPowerOf2) {
      print('$i is a power of 2');
    }
  }

  int value = 0;
  print('\nBit manipulation:');

  value = value | (1 << 3);
  print('Set bit 3: ${value.toRadixString(2).padLeft(8, '0')}');

  value = value | (1 << 5);
  print('Set bit 5: ${value.toRadixString(2).padLeft(8, '0')}');

  value = value & ~(1 << 3);
  print('Clear bit 3: ${value.toRadixString(2).padLeft(8, '0')}');

  value = value ^ (1 << 2);
  print('Toggle bit 2: ${value.toRadixString(2).padLeft(8, '0')}');

  bool isBit5Set = (value & (1 << 5)) != 0;
  bool isBit3Set = (value & (1 << 3)) != 0;
  print('Bit 5 is ${isBit5Set ? "set" : "not set"}');
  print('Bit 3 is ${isBit3Set ? "set" : "not set"}');

  int countBits = 170; 
  int bitCount = 0;
  int temp = countBits;
  while (temp > 0) {
    bitCount += temp & 1;
    temp >>= 1;
  }
  print('\nNumber of set bits in $countBits (${countBits.toRadixString(2)}): $bitCount');

  int x = 5;
  int y = 9;
  print('\nSwap without temp variable:');
  print('Before: x = $x, y = $y');
  x = x ^ y;
  y = x ^ y;
  x = x ^ y;
  print('After: x = $x, y = $y');

  int number = 18; 
  int rightmostBit = number & -number;
  print('\nRightmost set bit of $number (${number.toRadixString(2)}): $rightmostBit (${rightmostBit.toRadixString(2)})');

  int rgb = 0x3A5F9E; 
  int red = (rgb >> 16) & 0xFF;
  int green = (rgb >> 8) & 0xFF;
  int blue = rgb & 0xFF;
  print('\nExtract RGB from 0x${rgb.toRadixString(16).toUpperCase()}:');
  print('Red: $red, Green: $green, Blue: $blue');

  int toRotate = 0xF0; 
  int rotateLeft = ((toRotate << 2) | (toRotate >> 6)) & 0xFF;
  int rotateRight = ((toRotate >> 2) | (toRotate << 6)) & 0xFF;
  print('\nCircular shift (8-bit):');
  print('Original: ${toRotate.toRadixString(2).padLeft(8, '0')}');
  print('Rotate left by 2: ${rotateLeft.toRadixString(2).padLeft(8, '0')}');
  print('Rotate right by 2: ${rotateRight.toRadixString(2).padLeft(8, '0')}');
}

