@pragma('vm:never-inline')
@pragma('vm:entry-point')

int fn0(List<int> operations, int maxStackDepth) {
  List<int> log = [];
  int undoPenalty = 0;
  for (int op in operations) {
    if (op < 0) {
      int undoCount = -op;
      if (undoCount >= log.length) {
        log.clear();
      } else {
        for (int j = 0; j < undoCount; j++) {
          log.removeLast();
        }
      }
      undoPenalty++;
    } else if (op > 0 && maxStackDepth > 0) {
      if (log.length < maxStackDepth) {
        log.add(op);
      } else if (log.isNotEmpty) {
        log[log.length - 1] += op;
      }
    }
  }
  int totalDelay = undoPenalty;
  for (int entry in log) {
    totalDelay += entry;
  }
  return totalDelay;
}

