List<String> fn0(String manifest) {
  if (manifest.isEmpty) {
    return ['CHECK:00'];
  }
  List<String> entries = manifest.split(',');
  List<String> merged = [];
  String currentItem = '';
  int currentQty = 0;
  int totalWeightedSum = 0;

  for (String entry in entries) {
    List<String> parts = entry.split(':');
    if (parts.length != 2) continue;
    String item = parts[0].trim();
    int qty = int.tryParse(parts[1].trim()) ?? 0;
    if (qty <= 0) continue;

    if (item == currentItem) {
      currentQty += qty;
    } else {
      if (currentItem.isNotEmpty) {
        merged.add('$currentItem:$currentQty');
        int asciiSum = 0;
        for (int i = 0; i < currentItem.length; i++) {
          asciiSum += currentItem.codeUnitAt(i);
        }
        int weight = (asciiSum % 10) * currentQty;
        totalWeightedSum += weight;
      }
      currentItem = item;
      currentQty = qty;
    }
  }
  if (currentItem.isNotEmpty) {
    merged.add('$currentItem:$currentQty');
    int asciiSum = 0;
    for (int i = 0; i < currentItem.length; i++) {
      asciiSum += currentItem.codeUnitAt(i);
    }
    int weight = (asciiSum % 10) * currentQty;
    totalWeightedSum += weight;
  }

  int checksum = totalWeightedSum % 97;
  String checksumStr = checksum.toString().padLeft(2, '0');
  merged.add('CHECK:$checksumStr');
  return merged;
}

