@pragma('vm:never-inline')
@pragma('vm:entry-point')

List<String> fn0(List<String> strands, int minOccurrences) {
  Map<String, int> groupCounts = {};
  List<String> order = ['A', 'C', 'G', 'T'];

  for (String strand in strands) {
    Map<String, int> counts = {
      'A': 0,
      'C': 0,
      'G': 0,
      'T': 0,
    };

    for (int i = 0; i < strand.length; i++) {
      String base = strand[i];
      if (counts.containsKey(base)) {
        counts[base] = counts[base]! + 1;
      }
    }

    String key = '';
    for (String base in order) {
      if (counts[base]! >= minOccurrences) {
        key += base;
      }
    }

    if (key.isEmpty) {
      key = 'none';
    }

    groupCounts[key] = (groupCounts[key] ?? 0) + 1;
  }

  List<String> keys = groupCounts.keys.toList();
  keys.sort((a, b) {
    int countCompare = groupCounts[b]!.compareTo(groupCounts[a]!);
    if (countCompare != 0) {
      return countCompare;
    }
    return a.compareTo(b);
  });

  List<String> result = [];
  for (String key in keys) {
    result.add('$key:${groupCounts[key]}');
  }

  return result;
}

