Set<int> fn0(int currentFloor, Set<int> requests) {
  List<int> above = [];
  List<int> below = [];
  for (int floor in requests) {
    if (floor > currentFloor) {
      above.add(floor);
    } else if (floor < currentFloor) {
      below.add(floor);
    }
  }
  above.sort();
  below.sort((a, b) => b.compareTo(a));
  return <int>{...above, ...below};
}

