@pragma('vm:never-inline')
@pragma('vm:entry-point')

Map<String, int> fn0(List<String> tokens) {
  Map<String, int> tally = {};
  int state = 0;
  String? currentCandidate;
  Set<String> validCandidates = {'Alice', 'Bob', 'Carol'};
  for (String token in tokens) {
    if (state == 0) {
      if (token == 'BEGIN') state = 1;
    } else if (state == 1) {
      if (validCandidates.contains(token)) {
        currentCandidate = token;
        state = 2;
      } else if (token == 'BEGIN') {
        state = 1;
      } else {
        state = 0;
      }
    } else if (state == 2) {
      if (token == 'COUNT') {
        tally[currentCandidate!] = (tally[currentCandidate] ?? 0) + 1;
        state = 3;
      } else {
        state = 0;
        currentCandidate = null;
      }
    } else if (state == 3) {
      if (token == 'END') {
        state = 0;
        currentCandidate = null;
      } else if (token == 'BEGIN') {
        state = 1;
      }
    }
  }
  return tally;
}

