String fn0(List<int> setpoints, int targetTemp) {
  if (setpoints.isEmpty) return "No schedule";
  int low = 0;
  int high = setpoints.length - 1;
  int result = -1;
  while (low <= high) {
    int mid = (low + high) ~/ 2;
    if (setpoints[mid] <= targetTemp) {
      result = mid;
      low = mid + 1;
    } else {
      high = mid - 1;
    }
  }
  if (result == -1) {
    return "Below minimum: ${setpoints[0]}°C";
  }
  return "Set to ${setpoints[result]}°C";
}

