@pragma('vm:never-inline')
@pragma('vm:entry-point')

void fn0(List<String> args) {


  List<String> elements;
  if (args.isEmpty) {
    elements = ['a', 'b', 'c'];
    print('No arguments supplied. Using default elements: $elements');
    print('Usage examples:');
    print('  dart run program.dart 3            # subsets of [1, 2, 3]');
    print('  dart run program.dart red blue     # subsets of [red, blue]');
    print('');
  } else if (args.length == 1) {
    final n = int.tryParse(args[0]);
    if (n != null && n >= 0) {
      elements = List<String>.generate(n, (i) => '${i + 1}');
    } else {
      elements = args;
    }
  } else {
    elements = args;
  }

  final n = elements.length;
  final total = 1 << n;

  print('Input elements ($n): [${elements.join(', ')}]');
  print('Total subsets: $total');
  print('Subsets:');

  for (int mask = 0; mask < total; mask++) {
    final buffer = StringBuffer();
    buffer.write('[');
    bool first = true;
    for (int i = 0; i < n; i++) {
      if ((mask & (1 << i)) != 0) {
        if (!first) buffer.write(', ');
        buffer.write(elements[i]);
        first = false;
      }
    }
    buffer.write(']');
    print(buffer.toString());
  }
}

