@pragma('vm:never-inline')
@pragma('vm:entry-point')

void fn0() {

  final success = Result<String, int>.success("Operation completed");
  final failure = Result<String, int>.failure(404);

  void processResult(Result<String, int> result) {
    final message = switch (result) {
      Success<String, int>(value: var data) => 'Success: $data',
      Failure<String, int>(error: var err) => 'Failed with error: $err',
    };
    print(message);
  }

  processResult(success);
  processResult(failure);

  final some = Option<double>.some(3.14);
  final none = Option<double>.none();

  final doubled = some.map((value) => value * 2);
  final noneDoubled = none.map((value) => value * 2);

  print('Original: ${some.toString()}');
  print('Doubled: ${doubled.toString()}');
  print('None doubled: ${noneDoubled.toString()}');

  final left = Either<String, int>.left("Error message");
  final right = Either<String, int>.right(42);

  String foldResult(Either<String, int> either) {
    return either.fold(
      (leftValue) => 'Left side: $leftValue',
      (rightValue) => 'Right side: $rightValue',
    );
  }

  print(foldResult(left));
  print(foldResult(right));

  final results = <Result<String, int>>[
    Result.success("First"),
    Result.failure(500),
    Result.success("Second"),
    Result.failure(403),
  ];

  final successCount = results.where((r) => r is Success).length;
  final failureCount = results.where((r) => r is Failure).length;

  print('Success count: $successCount, Failure count: $failureCount');

  final chainedOption = Option<int>.some(10)
      .map((v) => v * 2)
      .flatMap((v) => v > 15 ? Option.some(v) : Option.none())
      .map((v) => v + 5);

  print('Chained option result: ${chainedOption.toString()}');

  final state = State<String, int, bool>.loading("Loading data", 0);
  final readyState = State<String, int, bool>.ready("Data loaded", 100, true);
  final errorState = State<String, int, bool>.error("Failed to load", -1, false);

  void printState(State<String, int, bool> s) {
    switch (s) {
      case Loading<String, int, bool>(message: var msg, progress: var prog):
        print('Loading: $msg (Progress: $prog%)');
      case Ready<String, int, bool>(data: var data, count: var count, success: var success):
        print('Ready: $data, Count: $count, Success: $success');
      case Error<String, int, bool>(error: var err, code: var code, recoverable: var rec):
        print('Error: $err (Code: $code, Recoverable: $rec)');
    }
  }

  printState(state);
  printState(readyState);
  printState(errorState);
}

sealed class Result<T, E> {
  const Result();

  factory Result.success(T value) => Success(value);
  factory Result.failure(E error) => Failure(error);
}

class Success<T, E> extends Result<T, E> {
  final T value;
  const Success(this.value);
}

class Failure<T, E> extends Result<T, E> {
  final E error;
  const Failure(this.error);
}

sealed class Option<T> {
  const Option();

  factory Option.some(T value) => Some(value);
  factory Option.none() => None();

  Option<R> map<R>(R Function(T) mapper) {
    return switch (this) {
      Some<T>(value: var val) => Option.some(mapper(val)),
      None<T>() => None<R>(),
    };
  }

  Option<R> flatMap<R>(Option<R> Function(T) mapper) {
    return switch (this) {
      Some<T>(value: var val) => mapper(val),
      None<T>() => None<R>(),
    };
  }

  @override
  String toString() {
    return switch (this) {
      Some<T>(value: var val) => 'Some($val)',
      None<T>() => 'None',
    };
  }
}

class Some<T> extends Option<T> {
  final T value;
  const Some(this.value);
}

class None<T> extends Option<T> {
  const None();
}

sealed class Either<L, R> {
  const Either();

  factory Either.left(L value) => Left(value);
  factory Either.right(R value) => Right(value);

  T fold<T>(T Function(L) leftMapper, T Function(R) rightMapper) {
    return switch (this) {
      Left<L, R>(value: var val) => leftMapper(val),
      Right<L, R>(value: var val) => rightMapper(val),
    };
  }
}

class Left<L, R> extends Either<L, R> {
  final L value;
  const Left(this.value);
}

class Right<L, R> extends Either<L, R> {
  final R value;
  const Right(this.value);
}

sealed class State<T, U, V> {
  const State();

  factory State.loading(T message, U progress) => Loading(message, progress);
  factory State.ready(T data, U count, V success) => Ready(data, count, success);
  factory State.error(T error, U code, V recoverable) => Error(error, code, recoverable);
}

class Loading<T, U, V> extends State<T, U, V> {
  final T message;
  final U progress;
  const Loading(this.message, this.progress);
}

class Ready<T, U, V> extends State<T, U, V> {
  final T data;
  final U count;
  final V success;
  const Ready(this.data, this.count, this.success);
}

class Error<T, U, V> extends State<T, U, V> {
  final T error;
  final U code;
  final V recoverable;
  const Error(this.error, this.code, this.recoverable);
}

