double fn0(List<int> departures) {

  if (departures.isEmpty) {
    return 0.0;
  }

  final Set<int> seen = <int>{};
  final List<int> unique = <int>[];
  for (final int t in departures) {
    final int norm = ((t % 1440) + 1440) % 1440;
    if (seen.add(norm)) {
      unique.add(norm);
    }
  }
  if (unique.isEmpty) {
    return 0.0;
  }

  unique.sort();

  double totalWait = 0.0;
  final int n = unique.length;
  for (int i = 0; i < n; i++) {
    final int current = unique[i];

    final int nextTrain = (i + 1 < n) ? unique[i + 1] : unique[0] + 1440;
    final int gap = nextTrain - current;
    totalWait += (gap * (gap - 1)) / 2.0;
  }

  return totalWait / 1440.0;
}

