List<int> fn0(List<int> modules, int k) {
  final List<int> result = [];
  final int n = modules.length;
  int i = 0;
  while (i < n) {
    if (modules[i] == 1) {
      int start = i;
      int runLen = 0;
      while (i < n && modules[i] == 1) {
        runLen++;
        i++;
      }
      if (runLen == k) {
        result.add(start);
      }
    } else {
      i++;
    }
  }
  return result;
}

