Set<int> fn0(List<int> ballotStream) {
  List<int> stack = [];
  Set<int> matched = {};
  for (int event in ballotStream) {
    if (event > 0) {
      stack.add(event);
    } else {
      int target = -event;
      if (stack.isNotEmpty && stack.last == target) {
        stack.removeLast();
        matched.add(target);
      }
    }
  }
  return matched;
}

