@pragma('vm:never-inline')
@pragma('vm:entry-point')

int fn0(int startDay, int breakDays, int totalDays) {
  if (startDay >= totalDays) return 0;
  int count = 0;
  int current = startDay;
  int cycle = 1 + breakDays;
  while (current < totalDays) {
    count++;
    current += cycle;
  }
  return count;
}

