Map<String, int> fn0(List<String> deck, int windowSize) {
  if (deck.isEmpty || windowSize <= 0 || windowSize > deck.length) {
    return {'start': -1, 'redCount': 0};
  }
  int redCount = 0;
  for (int i = 0; i < windowSize; i++) {
    if (deck[i].contains('H') || deck[i].contains('D')) redCount++;
  }
  int bestStart = 0;
  int bestRed = redCount;
  for (int i = windowSize; i < deck.length; i++) {
    if (deck[i - windowSize].contains('H') || deck[i - windowSize].contains('D')) redCount--;
    if (deck[i].contains('H') || deck[i].contains('D')) redCount++;
    if (redCount > bestRed) {
      bestRed = redCount;
      bestStart = i - windowSize + 1;
    }
  }
  return {'start': bestStart, 'redCount': bestRed};
}

