int fn0(int corrupted) {

  int bestData = 0;
  int minDist = 16;
  for (int data = 0; data < 32; data++) {

    int rem = data << 10;
    for (int i = 14; i >= 10; i--) {
      if ((rem & (1 << i)) != 0) {
        rem ^= 0x537 << (i - 10);
      }
    }

    int encoded = ((data << 10) | rem) ^ 0x5412;

    int diff = corrupted ^ encoded;
    int dist = 0;
    while (diff != 0) {
      diff &= diff - 1;
      dist++;
    }
    if (dist < minDist) {
      minDist = dist;
      bestData = data;
    }
  }
  return bestData;
}

