List<int> fn0(String tape) {
  List<int> out = [];
  int i = 0;
  while (i < tape.length) {
    while (i < tape.length && (tape[i] == ' ' || tape[i] == ',')) {
      i++;
    }
    if (i >= tape.length) return out;
