@pragma('vm:never-inline')
@pragma('vm:entry-point')

bool fn0(List<int> minutes) {
  bool solve(List<int> part) {
    if (part.length < 2) {
      return true;
    }
    for (int pivot = 0; pivot < part.length; pivot++) {
      int hub = part[pivot];
      List<int> earlier = [];
      List<int> later = [];
      bool ok = true;
      for (int i = 0; i < part.length; i++) {
        if (i == pivot) continue;
        int gap = (part[i] - hub).abs();
        if (gap == 0 || gap > 30) {
          ok = false;
          break;
        }
        if (part[i] < hub) {
          for (int v in earlier) {
            if (v == part[i]) return false;
          }
          earlier.add(part[i]);
        } else {
          for (int v in later) {
            if (v == part[i]) return false;
          }
          later.add(part[i]);
        }
      }
      if (ok && solve(earlier) && solve(later)) {
        return true;
      }
    }
    return false;
  }

  return solve(minutes);
}

