int fn0(List<int> sortedDistances) {
  int target = (sortedDistances.first + sortedDistances.last) ~/ 2;
  int low = 0, high = sortedDistances.length - 1;
  while (low <= high) {
    int mid = low + ((high - low) >> 1);
    if (sortedDistances[mid] <= target) low = mid + 1;
    else high = mid - 1;
