List<int> fn0(List<int> rolls, int singlesValue1, int singlesValue5) {
  final scores = <int>[];
  int i = 0;
  while (i < rolls.length) {
    int j = i;
    while (j < rolls.length && rolls[j] == rolls[i]) {
      j++;
    }
    int runLength = j - i;
    int value = rolls[i];
    if (runLength >= 3) {
      scores.add(value == 1 ? 1000 : value * 100);
      for (int k = 0; k < runLength - 3; k++) {
        if (value == 1) {
          scores.add(singlesValue1);
        } else if (value == 5) {
          scores.add(singlesValue5);
        }
      }
    } else {
      if (value == 1) {
        scores.add(singlesValue1);
      } else if (value == 5) {
        scores.add(singlesValue5);
      }
    }
    i = j;
  }
  return scores;
}

