int fn0(List<String> logs, int maxErrors) {

  int left = 0;
  int errorCount = 0;
  int best = 0;
  for (int right = 0; right < logs.length; right++) {
    if (logs[right].contains('ERROR')) {
      errorCount++;
    }
    while (errorCount > maxErrors && left <= right) {
      if (logs[left].contains('ERROR')) {
        errorCount--;
      }
      left++;
    }
    int windowSize = right - left + 1;
    if (windowSize > best) {
      best = windowSize;
    }
  }
  return best;
}

