@pragma('vm:never-inline')
@pragma('vm:entry-point')

double fn0(int seatingMask) {

  if (seatingMask == 0) return 0.0;

  int mask = seatingMask;
  int totalOccupied = 0;
  int sumOfSquares = 0;

  while (mask != 0) {

    int lowestBit = mask & (-mask);

    int blockMask = 0;
    int probe = lowestBit;
    while ((mask & probe) != 0) {
      blockMask |= probe;
      probe <<= 1;
    }

    int len = 0;
    int temp = blockMask;
    while (temp != 0) {
      len++;
      temp &= temp - 1;
    }

    sumOfSquares += len * len;
    totalOccupied += len;

    mask ^= blockMask;
  }

  return sumOfSquares / totalOccupied;
}

