void displayProfile(Map<String, dynamic> profile) {
  print('Username: ${profile['username']}');
  print('Display Name: ${profile['displayName']}');
  print('Email: ${profile['email']}');
  print('Bio: ${profile['bio']}');
  print('Avatar: ${profile['avatar']}');
  print('Theme: ${profile['theme']}');
  print('Language: ${profile['language']}');

  print('\nNotifications:');
  profile['notifications'].forEach((key, value) {
    print('  $key: ${value ? "Enabled" : "Disabled"}');
  });

  print('\nPrivacy:');
  profile['privacy'].forEach((key, value) {
    print('  $key: $value');
  });

  print('\nPreferences:');
  profile['preferences'].forEach((key, value) {
    print('  $key: ${value ? "Enabled" : "Disabled"}');
  });

  if (profile.containsKey('social')) {
    print('\nSocial Media:');
    profile['social'].forEach((key, value) {
      print('  $key: $value');
    });
  }

  if (profile.containsKey('interests')) {
    print('\nInterests: ${profile['interests'].join(', ')}');
  }
}

void validateProfile(Map<String, dynamic> profile) {
  List<String> issues = [];

  if (profile['username'] == null || profile['username'].isEmpty) {
    issues.add('Username is required');
  }

  if (profile['email'] == null || !isValidEmail(profile['email'])) {
    issues.add('Valid email is required');
  }

  if (profile['displayName'] == null || profile['displayName'].isEmpty) {
    issues.add('Display name is required');
  }

  if (profile['username'] != null && !isValidUsername(profile['username'])) {
    issues.add('Username must contain only letters, numbers, and underscores');
  }

  if (profile['bio'] != null && profile['bio'].length > 200) {
    issues.add('Bio must be 200 characters or less');
  }

  if (issues.isEmpty) {
    print('✓ Profile validation passed!');
  } else {
    print('✗ Profile validation failed:');
    issues.forEach((issue) => print('  - $issue'));
  }
}

bool isValidEmail(String email) {
  final emailRegex = RegExp(r'^[\w-\.]+@([\w-]+\.)+[\w-]{2,4}$');
  return emailRegex.hasMatch(email);
}

bool isValidUsername(String username) {
  final usernameRegex = RegExp(r'^[a-zA-Z0-9_]+$');
  return usernameRegex.hasMatch(username);
}

void generateProfileSummary(Map<String, dynamic> profile) {
  int completionScore = 0;
  int totalFields = 10;

  if (profile['displayName'] != null && profile['displayName'].isNotEmpty) completionScore++;
  if (profile['bio'] != null && profile['bio'].isNotEmpty) completionScore++;
  if (profile['avatar'] != null && profile['avatar'] != 'default.png') completionScore++;
  if (profile.containsKey('social') && profile['social'].isNotEmpty) completionScore++;
  if (profile.containsKey('interests') && profile['interests'].isNotEmpty) completionScore++;

  if (profile['theme'] != 'light') completionScore++;
  if (profile['language'] != 'en') completionScore++;

  bool privacyCustomized = false;
  profile['privacy'].forEach((key, value) {
    if ((key == 'profileVisibility' && value != 'public') ||
        (key == 'showEmail' && value != false) ||
        (key == 'showActivity' && value != true)) {
      privacyCustomized = true;
    }
  });
  if (privacyCustomized) completionScore++;

  bool notificationCustomized = false;
  profile['notifications'].forEach((key, value) {
    if ((key == 'email' && value != true) ||
        (key == 'push' && value != false) ||
        (key == 'sms' && value != false)) {
      notificationCustomized = true;
    }
  });
  if (notificationCustomized) completionScore++;

  bool preferencesCustomized = false;
  profile['preferences'].forEach((key, value) {
    if ((key == 'newsletter' && value != true) ||
        (key == 'autoplay' && value != false) ||
        (key == 'soundEffects' && value != true)) {
      preferencesCustomized = true;
    }
  });
  if (preferencesCustomized) completionScore++;

  double completionPercentage = (completionScore / totalFields) * 100;

  print('Profile Completion: ${completionPercentage.toStringAsFixed(0)}%');
  print('Customization Level: ${getCustomizationLevel(completionPercentage)}');

  int activeFeatures = 0;
  if (profile['notifications']['email'] == true) activeFeatures++;
  if (profile['notifications']['push'] == true) activeFeatures++;
  if (profile['notifications']['sms'] == true) activeFeatures++;
  if (profile['preferences']['newsletter'] == true) activeFeatures++;
  if (profile['preferences']['autoplay'] == true) activeFeatures++;
  if (profile['preferences']['soundEffects'] == true) activeFeatures++;

  print('Active Features: $activeFeatures');
  print('Privacy Level: ${profile['privacy']['profileVisibility']}');

  if (profile.containsKey('interests')) {
    print('Number of Interests: ${profile['interests'].length}');
  }

  if (profile.containsKey('social')) {
    print('Connected Social Accounts: ${profile['social'].length}');
  }
}

String getCustomizationLevel(double percentage) {
  if (percentage >= 90) return 'Expert';
  if (percentage >= 70) return 'Advanced';
  if (percentage >= 50) return 'Intermediate';
  if (percentage >= 30) return 'Basic';
  return 'Beginner';
}

