@pragma('vm:never-inline')
@pragma('vm:entry-point')

Set<int> fn0(List<String> commands) {
  Set<int> inventory = {};
  const int capacity = 3;
  for (final command in commands) {
    if (command.trim().isEmpty) continue;
    final parts = command.trim().split(RegExp(r'\s+'));
    if (parts.isEmpty) continue;
    final op = parts[0].toLowerCase();
    if (op == 'add' && parts.length == 2) {
      final item = int.tryParse(parts[1]);
      if (item != null && (inventory.contains(item) || inventory.length < capacity)) {
        inventory.add(item);
      }
    } else if (op == 'remove' && parts.length == 2) {
      final item = int.tryParse(parts[1]);
      if (item != null) {
        inventory.remove(item);
      }
    } else if (op == 'combine' && parts.length == 4) {
      final id1 = int.tryParse(parts[1]);
      final id2 = int.tryParse(parts[2]);
      final id3 = int.tryParse(parts[3]);
      if (id1 != null && id2 != null && id3 != null) {
        if (inventory.contains(id1) && inventory.contains(id2)) {
          inventory.remove(id1);
          inventory.remove(id2);
          inventory.add(id3);
        }
      }
    }
  }
  return inventory;
}

