bool fn0(int phaseCode) {
  int lowerNibble = phaseCode & 0xF;
  int upperNibble = (phaseCode >> 4) & 0xF;

  int activeBits = 0;
  int tmp = lowerNibble;
  while (tmp > 0) { activeBits += tmp & 1; tmp >>= 1; }

  int sensorBits = 0;
  tmp = upperNibble;
  while (tmp > 0) { sensorBits += tmp & 1; tmp >>= 1; }
  return activeBits == 1 && sensorBits >= 2;
}

