double fn0(List<int> points) {
  if (points.length < 6 || points.length % 2 != 0) return 0.0;
  int n = points.length ~/ 2;
  int sum = 0;
  for (int i = 0; i < n; i++) {
    int x = points[2 * i];
    int y = points[2 * i + 1];
    int next = (i + 1) % n;
    int nx = points[2 * next];
    int ny = points[2 * next + 1];
    sum += x * ny - nx * y;
  }
