List<int> fn0(String digits, int modulus) {
  var out = <int>[];
  var rem = 0;
  for (var i = 0; i < digits.length; i++) {
    var d = digits.codeUnitAt(i) - 48;
    rem = (rem * 10 + d) % modulus;
    var a = d, b = modulus;
    while (b != 0) {
      var t = a % b;
      a = b;
      b = t;
    }
    if (a == 1 && rem == d % modulus) out.add(i);
  }
  return out;
}

