List<String> fn0(String encoded) {
  if (encoded.isEmpty) return [];

  List<String> result = [];
  int currentCharge = 0;

  List<String> segments = encoded.split(',');
  for (String segment in segments) {
    int xIndex = segment.indexOf('x');
    if (xIndex == -1) continue;

    String deltaStr = segment.substring(0, xIndex);
    String countStr = segment.substring(xIndex + 1);

    int delta = int.parse(deltaStr);
    int count = int.parse(countStr);

    for (int i = 0; i < count; i++) {
      currentCharge += delta;
      if (currentCharge < 0) currentCharge = 0;
      if (currentCharge > 100) currentCharge = 100;
      result.add('$currentCharge%');
    }
  }

  return result;
}

