double fn0(List<String> commands) {


  final List<int> buffer = [];
  int deliveredTotal = 0;
  int deliveredCount = 0;
  for (final cmd in commands) {
    if (cmd.startsWith('SEND ')) {
      buffer.add(int.parse(cmd.substring(5)));
    } else if (cmd == 'ACK') {
      if (buffer.isNotEmpty) {
        deliveredTotal += buffer.removeLast();
        deliveredCount++;
      }
    } else if (cmd == 'DROP') {
      if (buffer.isNotEmpty) {
        buffer.removeLast();
      }
    }
  }
  if (deliveredCount == 0) return 0.0;
  return deliveredTotal / deliveredCount;
}

