Set<int> fn0(List<List<int>> rounds) {
  Set<int> winningSums = {};
  for (final round in rounds) {
    if (round.length >= 3 && !round.contains(1)) {
      int sum = round.fold(0, (a, b) => a + b);
      if (sum > 10) {
        Set<int> seen = {};
        bool hasPair = false;
        for (final die in round) {
          if (!seen.add(die)) {
            hasPair = true;
            break;
          }
        }
        if (hasPair) {
          winningSums.add(sum);
        }
      }
    }
  }
  return winningSums;
}

