@pragma('vm:never-inline')
@pragma('vm:entry-point')

int fn0(List<int> buckets) {
  if (buckets.isEmpty) {
    return 0;
  }
  int low = 1;
  int high = buckets.length;
  int answer = 0;
  while (low <= high) {
    int mid = (low + high) >> 1;
    bool found = false;
    for (int start = 0; start + mid <= buckets.length; start++) {
      bool usedRepair = false;
      bool valid = true;
      for (int i = start; i < start + mid; i++) {
        if (buckets[i] >= mid) {
          continue;
        }
        bool repaired = false;
        if (!usedRepair) {
          if (i > start && buckets[i - 1] + buckets[i] >= mid * 2) {
            repaired = true;
          } else if (i + 1 < start + mid && buckets[i + 1] + buckets[i] >= mid * 2) {
            repaired = true;
          }
        }
        if (!repaired) {
          valid = false;
          break;
        }
        usedRepair = true;
      }
      if (valid) {
        found = true;
        break;
      }
    }
    if (found) {
      answer = mid;
      low = mid + 1;
    } else {
      high = mid - 1;
    }
  }
  return answer;
}

