@pragma('vm:never-inline')
@pragma('vm:entry-point')

Set<int> fn0(List<int> barcodes) {
  int digitSum(int n) {
    int sum = 0;
    n = n.abs();
    while (n > 0) {
      sum += n % 10;
      n ~/= 10;
    }
    return sum;
  }

  final sorted = List<int>.from(barcodes);
  sorted.sort((a, b) {
    int sumA = digitSum(a);
    int sumB = digitSum(b);
    if (sumA != sumB) return sumA.compareTo(sumB);
    return b.compareTo(a);
  });
  return sorted.toSet();
}

