@pragma('vm:never-inline')
@pragma('vm:entry-point')

Map<String, int> fn0(List<String> rows) {
  if (rows.isEmpty) {
    return {};
  }

  int width = 0;
  for (final row in rows) {
    if (row.length > width) {
      width = row.length;
    }
  }

  bool columnHasInk(int column) {
    for (final row in rows) {
      if (column < row.length && row[column] != ' ') {
        return true;
      }
    }
    return false;
  }

  final Map<String, int> counts = {};
  int col = 0;

  while (col < width) {
    while (col < width && !columnHasInk(col)) {
      col++;
    }

    if (col >= width) {
      break;
    }

    final int start = col;

    while (col < width && columnHasInk(col)) {
      col++;
    }

    final int end = col;
    final List<String> piece = [];

    for (final row in rows) {
      final StringBuffer buffer = StringBuffer();
      for (int i = start; i < end; i++) {
        buffer.write(i < row.length ? row[i] : ' ');
      }

      String trimmed = buffer.toString();
      while (trimmed.isNotEmpty && trimmed.endsWith(' ')) {
        trimmed = trimmed.substring(0, trimmed.length - 1);
      }
      piece.add(trimmed);
    }

    while (piece.isNotEmpty && piece.first.trim().isEmpty) {
      piece.removeAt(0);
    }

    while (piece.isNotEmpty && piece.last.trim().isEmpty) {
      piece.removeLast();
    }

    final String token = piece.join('\n');
    counts[token] = (counts[token] ?? 0) + 1;
  }

  return counts;
}

