String fn0(List<int> gaps) {
  int day = 0;
  int streak = 0;
  int bestStreak = 0;
  int monthWraps = 0;
  for (final gap in gaps) {
    if (gap <= 0) {
      streak = 0;
    } else {
      int previous = day;
      day += gap;
      if (gap == 1) {
        streak++;
      } else if (gap <= 3) {
        streak = 1;
      } else {
        streak = 0;
