List<String> fn0(List<int> resistances, List<int> targets) {
  List<String> results = [];
  for (int target in targets) {
    int first = -1, low = 0, high = resistances.length - 1;
    while (low <= high) {
      int mid = (low + high) ~/ 2;
      if (resistances[mid] == target) { first = mid; high = mid - 1; }
      else if (resistances[mid] < target) low = mid + 1;
      else high = mid - 1;
    }
    int last = -1;
    if (first != -1) {
      low = first; high = resistances.length - 1;
      while (low <= high) {
        int mid = (low + high) ~/ 2;
        if (resistances[mid] == target) { last = mid; low = mid + 1; }
        else if (resistances[mid] < target) low = mid + 1;
        else high = mid - 1;
      }
      results.add('${first + 1}:${last + 1}');
    } else {
      results.add('-1');
    }
  }
  return results;
}

