@pragma('vm:never-inline')
@pragma('vm:entry-point')

double fn0(String timetable) {
  if (timetable.isEmpty) return 0.0;
  List<int> arrivals = [];
  int i = 0;
  int n = timetable.length;
  while (i < n) {
    while (i < n && timetable[i] == ' ') i++;
    if (i >= n) break;
    int hour = 0;
    while (i < n && timetable[i] != ':') {
      hour = hour * 10 + (timetable.codeUnitAt(i) - 48);
      i++;
    }
    i++;
    int minute = 0;
    while (i < n && timetable[i] != ',' && timetable[i] != ' ') {
      minute = minute * 10 + (timetable.codeUnitAt(i) - 48);
      i++;
    }
    arrivals.add(hour * 60 + minute);
    if (i < n && timetable[i] == ',') i++;
  }
  if (arrivals.length < 2) return 0.0;
  List<int> durations = [];
  for (int j = 1; j < arrivals.length; j++) {
    int diff = arrivals[j] - arrivals[j - 1];
    if (diff < 0) diff += 1440;
    durations.add(diff);
  }
  int sum = 0;
  for (int d in durations) sum += d;
  return sum / durations.length.toDouble();
}

