Set<int> fn0(List<int> itemPositions) {
  final itemSet = itemPositions.toSet();
  final dropZones = <int>{};
  for (final pos in itemPositions) {
    final row = pos ~/ 100;
    final col = pos % 100;
    final neighbors = [
      if (row > 0) (row - 1) * 100 + col,
      if (row < 99) (row + 1) * 100 + col,
      if (col > 0) row * 100 + (col - 1),
      if (col < 99) row * 100 + (col + 1),
    ];
    for (final n in neighbors) {
      if (!itemSet.contains(n)) {
        dropZones.add(n);
      }
    }
  }
  return dropZones;
}

