@pragma('vm:never-inline')
@pragma('vm:entry-point')

int fn0(List<String> edits) {
  var stack = <int>[];
  for (var e in edits) {
    if (e == '!') {
      if (stack.isNotEmpty) stack.removeLast();
    } else {
      var v = e.endsWith('*') ? e.length - 1 : -e.length;
      stack.add(v);
    }
  }
  var sum = 0;
  for (var v in stack) {
    sum += v > 0 ? v : 1;
  }
  return sum;
}

