List<int> fn0(List<List<int>> data) {
  var q = data[0];
  int even = 0, odd = 0;
  for (int i = 1; i < data.length; i++) {
    var p = data[i];
    int d = (p[0] - q[0]).abs() + (p[1] - q[1]).abs();
    if (d % 2 == 0) even += p[2]; else odd += p[2];
  }
  return [even, odd];
}

