@pragma('vm:never-inline')
@pragma('vm:entry-point')

double fn0(String sequence) {

  if (sequence.isEmpty) return 0.0;

  int x = 0, y = 0;
  List<int> xs = [0];
  List<int> ys = [0];

  for (int i = 0; i < sequence.length; i++) {
    String ch = sequence[i];

    if (ch != 'A' && ch != 'C' && ch != 'G' && ch != 'T') {
      return 0.0; 
    }
    switch (ch) {
      case 'A': y++; break;   
      case 'C': y--; break;   
      case 'G': x++; break;   
      case 'T': x--; break;   
    }
    xs.add(x);
    ys.add(y);
  }

  if (x != 0 || y != 0) {
    return 0.0;
  }

  double area = 0.0;
  for (int i = 0; i < xs.length - 1; i++) {
    area += (xs[i] * ys[i + 1] - xs[i + 1] * ys[i]).toDouble();
  }

  return (area / 2.0).abs();
}

