@pragma('vm:never-inline')
@pragma('vm:entry-point')

void fn0() {

  List<int> dimensions = [10, 20, 30, 40, 30];
  int n = dimensions.length - 1; 

  List<List<int>> m = List.generate(n + 1, (_) => List.filled(n + 1, 0));

  List<List<int>> s = List.generate(n + 1, (_) => List.filled(n + 1, 0));

  for (int l = 2; l <= n; l++) {
    for (int i = 1; i <= n - l + 1; i++) {
      int j = i + l - 1;
      m[i][j] = 999999999; 

      for (int k = i; k < j; k++) {

        int cost = m[i][k] + m[k + 1][j] + dimensions[i - 1] * dimensions[k] * dimensions[j];

        if (cost < m[i][j]) {
          m[i][j] = cost;
          s[i][j] = k;
        }
      }
    }
  }

  void printOptimalParens(List<List<int>> s, int i, int j) {
    if (i == j) {
      print('A$i');
    } else {
      print('(');
      printOptimalParens(s, i, s[i][j]);
      printOptimalParens(s, s[i][j] + 1, j);
      print(')');
    }
  }

  print('Matrix Chain Multiplication Dynamic Programming Solution');
  print('=========================================================');
  print('Matrix dimensions:');
  for (int i = 1; i <= n; i++) {
    print('  Matrix A$i: ${dimensions[i-1]} x ${dimensions[i]}');
  }
  print('');

  print('Minimum cost table:');
  for (int i = 1; i <= n; i++) {
    String row = '';
    for (int j = 1; j <= n; j++) {
      if (j >= i) {
        row += '${m[i][j]}'.padLeft(8);
      } else {
        row += ''.padLeft(8);
      }
    }
    print('  Row $i: $row');
  }
  print('');

  print('Split point table:');
  for (int i = 1; i <= n; i++) {
    String row = '';
    for (int j = 1; j <= n; j++) {
      if (j > i) {
        row += '${s[i][j]}'.padLeft(8);
      } else {
        row += ''.padLeft(8);
      }
    }
    print('  Row $i: $row');
  }
  print('');

  print('Minimum number of scalar multiplications: ${m[1][n]}');
  print('');

  print('Optimal parenthesization:');
  print('  ');
  printOptimalParens(s, 1, n);
  print('');

  print('\n=========================================================');
  print('Second example with different dimensions:');
  List<int> dims2 = [5, 10, 3, 12, 5, 50, 6];
  int n2 = dims2.length - 1;

  List<List<int>> m2 = List.generate(n2 + 1, (_) => List.filled(n2 + 1, 0));
  List<List<int>> s2 = List.generate(n2 + 1, (_) => List.filled(n2 + 1, 0));

  for (int l = 2; l <= n2; l++) {
    for (int i = 1; i <= n2 - l + 1; i++) {
      int j = i + l - 1;
      m2[i][j] = 999999999;

      for (int k = i; k < j; k++) {
        int cost = m2[i][k] + m2[k + 1][j] + dims2[i - 1] * dims2[k] * dims2[j];

        if (cost < m2[i][j]) {
          m2[i][j] = cost;
          s2[i][j] = k;
        }
      }
    }
  }

  print('Matrix dimensions:');
  for (int i = 1; i <= n2; i++) {
    print('  Matrix A$i: ${dims2[i-1]} x ${dims2[i]}');
  }
  print('');
  print('Minimum number of scalar multiplications: ${m2[1][n2]}');
  print('');
  print('Optimal parenthesization:');
  print('  ');

  void printOptimalParens2(List<List<int>> s, int i, int j) {
    if (i == j) {
      print('A$i');
    } else {
      print('(');
      printOptimalParens2(s, i, s[i][j]);
      printOptimalParens2(s, s[i][j] + 1, j);
      print(')');
    }
  }

  printOptimalParens2(s2, 1, n2);
  print('');
}

