Map<String, int> fn0(List<String> telemetry, double lowThreshold, double highThreshold) {
  Set<String> sensorIds = {};
  for (var entry in telemetry) {
    var parts = entry.split(',');
    if (parts.length == 2) {
      sensorIds.add(parts[0]);
    }
  }
  Map<String, int> result = {};
  for (var sensorId in sensorIds) {
    result['${sensorId}_low'] = 0;
    result['${sensorId}_medium'] = 0;
    result['${sensorId}_high'] = 0;
  }
  for (var entry in telemetry) {
    var parts = entry.split(',');
    if (parts.length != 2) continue;
    var sensorId = parts[0];
    double reading = double.parse(parts[1]);
    String bin;
    if (reading < lowThreshold) {
      bin = 'low';
    } else if (reading <= highThreshold) {
      bin = 'medium';
    } else {
      bin = 'high';
    }
    var key = '${sensorId}_$bin';
    result[key] = result[key]! + 1;
  }
  return result;
}

