int fn0(List<int> initialModules, String commands) {
  var stack = List<int>.from(initialModules);
  int black = stack.fold(0, (a, b) => a + b);
  for (int i = 0; i < commands.length; i++) {
    if (commands[i] == 'B') { stack.add(1); black++; }
    else if (commands[i] == 'W') { stack.add(0); }
    else { var popped = stack.removeLast(); if (popped == 1) black--; }
  }
  return black;
}

