@pragma('vm:never-inline')
@pragma('vm:entry-point')

void fn0() {
  print('=== Dart 3 Variable Patterns Demo ===\n');

  var point = (2, 3);
  var (x, y) = point;
  print('Record (positional): point = $point → x = $x, y = $y');

  var person = (name: 'Alice', age: 30);
  var (name: n, age: a) = person;
  print('Record (named): person = $person → name = $n, age = $a');

  var numbers = [10, 20, 30, 40, 50];
  var [first, second, ...rest] = numbers;
  print('List: $numbers → first = $first, second = $second, rest = $rest');

  var config = {'host': 'localhost', 'port': 8080, 'secure': true};
  var {'host': h, 'port': p, 'secure': s} = config;
  print('Map: $config → host = $h, port = $p, secure = $s');

  var shape = (4, 4);
  switch (shape) {
    case (var width, var height) when width == height:
      print('Switch: Detected a square of side $width');
      break;
    case (var width, var height):
      print('Switch: Detected a rectangle ${width}×$height');
      break;
  }

  var input = [0, 99];
  if (input case [0, var value]) {
    print('If-case: List starts with 0, second value = $value');
  } else {
    print('If-case: Other list pattern: $input');
  }
}

