  List<int>? remoteScores =
      Random(0).nextBool() ? [10, 20, 30] : null; 
  List<int> scores = [5, ...?remoteScores, 40];
  print('Scores list (with spread): $scores');

  (payload?['settings'] as Map?)?..['language'] = 'en'
                                 ..['timezone'] = 'UTC';
  print('Final payload: $payload');
