  if (filtered.length < 2) return 0.0;
  filtered.sort();
  int totalGap = 0;
  for (int i = 1; i < filtered.length; i++) {
    totalGap += filtered[i] - filtered[i - 1];
  }
  return totalGap / (filtered.length - 1);
}

