@pragma('vm:never-inline')
@pragma('vm:entry-point')

bool fn0(List<int> events) {
  List<int> stack = [];
  Set<int> active = {};
  int maxConcurrent = 0;
  int current = 0;
  for (int e in events) {
    if (e > 0) {
      if (active.contains(e)) return false;
      stack.add(e);
      active.add(e);
      current++;
      if (current > maxConcurrent) maxConcurrent = current;
    } else {
      int id = -e;
      if (stack.isEmpty || stack.last != id) return false;
      stack.removeLast();
      active.remove(id);
      current--;
    }
  }
  if (maxConcurrent > 3) return false;
  return stack.isEmpty;
}

