String fn0(String report, int minimum) {
  var out = <String>[];
  for (var part in report.split('|')) {
    if (part.isEmpty) {
      continue;
    }
    var bits = part.split(':');
    var qty = int.parse(bits[1]);
    if (qty <= minimum) {
      out.add(qty == minimum ? '${bits[0]}=0' : '${bits[0]}!${minimum - qty}');
    }
  }
  return out.join(',');
}

