@pragma('vm:never-inline')
@pragma('vm:entry-point')

void fn0() {

  String input = "TOBEORNOTTOBEORTOBEORNOT";
  print("Original string: $input");
  print("Original size: ${input.length} characters");

  List<int> compressed = [];
  Map<String, int> dictionary = {};
  int dictSize = 256;

  for (int i = 0; i < 256; i++) {
    dictionary[String.fromCharCode(i)] = i;
  }

  String w = "";
  for (int i = 0; i < input.length; i++) {
    String c = input[i];
    String wc = w + c;

    if (dictionary.containsKey(wc)) {
      w = wc;
    } else {
      compressed.add(dictionary[w]!);

      dictionary[wc] = dictSize++;
      w = c;
    }
  }

  if (w.isNotEmpty) {
    compressed.add(dictionary[w]!);
  }

  print("\nCompressed: $compressed");
  print("Compressed size: ${compressed.length} codes");

  Map<int, String> decompDict = {};
  int decompDictSize = 256;

  for (int i = 0; i < 256; i++) {
    decompDict[i] = String.fromCharCode(i);
  }

  String decompressed = "";
  String previous = "";

  for (int i = 0; i < compressed.length; i++) {
    int code = compressed[i];
    String entry = "";

    if (decompDict.containsKey(code)) {
      entry = decompDict[code]!;
    } else if (code == decompDictSize) {
      entry = previous + previous[0];
    } else {
      print("Error: Invalid compressed code");
      return;
    }

    decompressed += entry;

    if (previous.isNotEmpty) {
      decompDict[decompDictSize++] = previous + entry[0];
    }

    previous = entry;
  }

  print("\nDecompressed string: $decompressed");
  print("Decompressed size: ${decompressed.length} characters");

  if (input == decompressed) {
    print("\n✓ Compression and decompression successful!");
    double compressionRatio = (compressed.length * 100.0) / input.length;
    print("Compression ratio: ${compressionRatio.toStringAsFixed(2)}%");
  } else {
    print("\n✗ Error: Decompressed string doesn't match original!");
  }

  print("\n" + "="*50);
  print("Testing with another string...\n");

  String input2 = "ABABABABABABABABAB";
  print("Original string: $input2");

  List<int> compressed2 = [];
  Map<String, int> dict2 = {};
  int dictSize2 = 256;

  for (int i = 0; i < 256; i++) {
    dict2[String.fromCharCode(i)] = i;
  }

  String w2 = "";
  for (int i = 0; i < input2.length; i++) {
    String c = input2[i];
    String wc = w2 + c;

    if (dict2.containsKey(wc)) {
      w2 = wc;
    } else {
      compressed2.add(dict2[w2]!);
      dict2[wc] = dictSize2++;
      w2 = c;
    }
  }

  if (w2.isNotEmpty) {
    compressed2.add(dict2[w2]!);
  }

  print("Compressed: $compressed2");
  print("Compression ratio: ${(compressed2.length * 100.0 / input2.length).toStringAsFixed(2)}%");

  Map<int, String> decompDict2 = {};
  int decompDictSize2 = 256;

  for (int i = 0; i < 256; i++) {
    decompDict2[i] = String.fromCharCode(i);
  }

  String decompressed2 = "";
  String prev2 = "";

  for (int i = 0; i < compressed2.length; i++) {
    int code = compressed2[i];
    String entry = "";

    if (decompDict2.containsKey(code)) {
      entry = decompDict2[code]!;
    } else if (code == decompDictSize2) {
      entry = prev2 + prev2[0];
    }

    decompressed2 += entry;

    if (prev2.isNotEmpty) {
      decompDict2[decompDictSize2++] = prev2 + entry[0];
    }

    prev2 = entry;
  }

  print("Decompressed: $decompressed2");
  print("Match: ${input2 == decompressed2 ? '✓' : '✗'}");
}

