@pragma('vm:never-inline')
@pragma('vm:entry-point')

int fn0(List<List<int>> grid, int rounds) {
  if (grid.isEmpty || grid[0].isEmpty || rounds <= 0) {
    return 0;
  }
  int rows = grid.length;
  int cols = grid[0].length;
  List<List<int>> current = grid.map((row) => List<int>.from(row)).toList();
  List<List<int>> dirs = [[-1, 0], [1, 0], [0, -1], [0, 1]];
  int totalScore = 0;

  for (int r = 0; r < rounds; r++) {
    List<List<int>> next = current.map((row) => List<int>.from(row)).toList();
    int roundScore = 0;
    for (int i = 0; i < rows; i++) {
      for (int j = 0; j < cols; j++) {
        int val = current[i][j];
        int same = 0, higher = 0, lower = 0;
        for (List<int> d in dirs) {
          int ni = i + d[0], nj = j + d[1];
          if (ni >= 0 && ni < rows && nj >= 0 && nj < cols) {
            if (current[ni][nj] == val) {
              same++;
            } else if (current[ni][nj] > val) {
              higher++;
            } else {
              lower++;
            }
          }
        }
        roundScore += same;
        if (higher > lower) {
          next[i][j] = val >= 6 ? 6 : val + 1;
        } else if (lower > higher) {
          next[i][j] = val <= 1 ? 1 : val - 1;
        }
      }
    }
    totalScore += roundScore;
    current = next;
  }
  return totalScore;
}

