  var out = <int>[];
  for (var r = 0; r < cycles.length; r++) {
    var row = cycles[r];
    var score = 0;
    for (var c = 1; c < row.length; c++) {
      var diff = row[c] - row[c - 1];
      if (diff >= 4) score++;
      if (diff <= -4) score--;
    }
    if (score == 1) out.add(r);
  }
  return out;
}

