Map<String, int> fn0(List<int> packetSizes) {
  Set<int> seen = <int>{};
  Set<int> multiples = <int>{};
  for (int size in packetSizes) {
    if (seen.contains(size)) {
      if (!multiples.contains(size)) {
        multiples.add(size);
      }
    } else {
      seen.add(size);
    }
  }
  return {
    'unique': seen.length - multiples.length,
    'duplicate': multiples.length
  };
}

