  for (int r = 0; r < grid.length; r++) {
    if (grid[r].isEmpty) continue;
    for (int c = 0; c < grid[r].length; c++) {
      int phase = grid[r][c];
      if (phase < 0 || phase > 2) {
        score += 5;
        continue;
      }
      if ((r == 0 || c == 0) && phase == 1) score += 1;
      if (c > 0) {
        int left = grid[r][c - 1];
        if (left >= 0 && left <= 2) {
