Set<int> fn0(int steps) {
  if (steps < 0) return {};
  Set<int> current = {0};
  List<int> dr = [-1, 1, 0, 0];
  List<int> dc = [0, 0, -1, 1];
  for (int s = 0; s < steps; s++) {
    Set<int> next = {};
    for (int sq in current) {
      int r = sq ~/ 8;
      int c = sq % 8;
      for (int d = 0; d < 4; d++) {
        int nr = r + dr[d];
        int nc = c + dc[d];
        if (nr >= 0 && nr < 8 && nc >= 0 && nc < 8) {
          next.add(nr * 8 + nc);
        }
      }
    }
    current = next;
  }
  return current;
}

