List<String> fn0(List<int> dailyPackets, int startIndex) {
  List<String> result = [];
  int n = dailyPackets.length;
  int i = 0;
  while (i < n) {
    if (dailyPackets[i] > 0) {
      int j = i;
      int total = 0;
      while (j < n && dailyPackets[j] > 0) {
        total += dailyPackets[j];
        j++;
      }
      result.add('Days ${startIndex + i}-${startIndex + j - 1}: ${total}');
      i = j;
    } else {
      i++;
    }
  }
  return result;
}

