double fn0(List<int> arrivalSeconds, int greenSec, int yellowSec, int redSec) {
  int cycle = greenSec + yellowSec + redSec;
  if (arrivalSeconds.isEmpty) return 0.0;
  int totalDelay = 0;
  for (int t in arrivalSeconds) {
    int pos = t % cycle;
    if (pos >= greenSec + yellowSec) {
      totalDelay += cycle - pos;
    }
  }
  return totalDelay / arrivalSeconds.length;
}

