String fn0(List<String> bins) {
  var items = [...bins];
  items.sort((a, b) {
    var pa = a.split(':');
    var pb = b.split(':');
    var qa = int.parse(pa[1]);
    var qb = int.parse(pb[1]);
    return qa != qb ? qa - qb : pa[0].compareTo(pb[0]);
  });
  var out = <String>[];
  for (var e in items) {
    var p = e.split(':');
    if (int.parse(p[1]) <= 3) out.add(p[0]);
  }
  return out.join('|');
}

