int fn0(List<int> requests, int current) {
  if (requests.isEmpty) return 0;
  int minIdx = 0, minDiff = (requests[0] - current).abs();
  for (int i = 1; i < requests.length; i++) {
    int diff = (requests[i] - current).abs();
    if (diff < minDiff) { minDiff = diff; minIdx = i; }
  }
  int next = requests[minIdx];
  return minDiff + fn0(requests.toList()..removeAt(minIdx), next);
}

