int fn0(int version, int k) {
  int len = 4 * version + 17, lo = 0, hi = len - 1;
  while (lo < hi) {
    int mid = (lo + hi) ~/ 2;
    int cnt = mid + 1 - (mid >= 6 ? ((mid - 6) ~/ 2) + 1 : 0);
    if (cnt >= k) hi = mid; else lo = mid + 1;
  }
  return lo;
}

