@pragma('vm:never-inline')
@pragma('vm:entry-point')

String fn0(List<int> hashValues) {
  const B = 11;
  var cnt = List.filled(B, 0);
  for (var h in hashValues) cnt[h % B]++;
  double avg = hashValues.length / B;
  var res = <String>[];
  for (int i = 0; i < B; i++) if (cnt[i] > avg) res.add(i.toString());
  return res.isEmpty ? 'none' : res.join(',');
}

