bool fn0(List<String> sequences) {

  final unique = sequences.toSet().toList();

  final revCompMap = <String, String>{};
  for (final seq in unique) {
    final buffer = StringBuffer();
    for (int i = seq.length - 1; i >= 0; i--) {
      final base = seq[i];
      switch (base) {
        case 'A': buffer.write('T'); break;
        case 'T': buffer.write('A'); break;
        case 'C': buffer.write('G'); break;
        case 'G': buffer.write('C'); break;
        default: buffer.write(base); 
      }
    }
    revCompMap[seq] = buffer.toString();
  }

  for (final seq in unique) {
    final revComp = revCompMap[seq]!;
    if (revComp != seq && unique.contains(revComp)) {
      return true;
    }
  }
  return false;
}

