  expect(candidate([0, 1, 2, 49]), 'all-down');
  expect(candidate([0, 1, 2, 50]), '50c');
  expect(candidate([0, 12, 49, 50, 88]), '50c');
  expect(candidate([0, 12, 49, 51, 88]), '51c');
  expect(candidate([50, 50, 99]), '50c');
  expect(candidate([48, 49, 50, 51]), '50c');
