@pragma('vm:never-inline')
@pragma('vm:entry-point')

String fn0(List<int> crateIds) {
  if (crateIds.isEmpty) return "0";
  int gcd = crateIds.first;
  for (int id in crateIds.skip(1)) {
    int a = gcd, b = id;
    while (b != 0) {
      int t = b;
      b = a % b;
      a = t;
    }
    gcd = a;
    if (gcd == 1) break;
  }
  if (gcd == 0) return "0";
  String binary = "";
  int n = gcd;
  while (n > 0) {
    binary = (n % 2).toString() + binary;
    n ~/= 2;
  }
  return binary.isEmpty ? "0" : binary;
}

