int fn0(List<int> actions) {
  if (actions.isEmpty) return 0;
  List<int> votes = [];
  for (int action in actions) {
    if (action > 0) {
      votes.add(action);
    } else if (action == -1) {
      if (votes.isNotEmpty) {
        votes.removeLast();
      }
    } else if (action < -1) {
      int fn0 = -action;
      for (int i = votes.length - 1; i >= 0; i--) {
        if (votes[i] == fn0) {
          votes.removeAt(i);
          break;
        }
      }
    }
  }
  return votes.length;
}

