Set<int> fn0(List<int> phaseTimes, int moment) {
  int left = 0;
  int right = phaseTimes.length - 1;
  while (left <= right) {
    int mid = (left + right) ~/ 2;
    if (phaseTimes[mid] < moment) {
      left = mid + 1;
    } else {
      right = mid - 1;
    }
  }
  Set<int> result = {};
  if (right >= 0) result.add(phaseTimes[right]);
  if (left < phaseTimes.length) result.add(phaseTimes[left]);
  return result;
}

