double fn0(List<List<int>> rounds) {



  double score = 0.0;
  double multiplier = 1.0;
  int previous = -1;
  bool hasPrevious = false;
  for (int r = 0; r < rounds.length; r++) {
    final List<int> row = rounds[r];
    final bool leftToRight = r % 2 == 0;
    for (int i = 0; i < row.length; i++) {
      final int c = leftToRight ? i : row.length - 1 - i;
      final int v = row[c];
      if (hasPrevious && v == previous) {
        multiplier = multiplier * 2.0;
        if (multiplier > 8.0) multiplier = 8.0;
      } else {
        multiplier = 1.0;
      }
      if (v == 1) {
        score -= 0.5 * multiplier;
      } else {
        score += v * multiplier;
      }
      previous = v;
      hasPrevious = true;
    }
  }
  return score;
}

