  final dp = List<int>.filled(codes.length, 1);
  final out = <String>[];
  for (var i = 0; i < codes.length; i++) {
    if (i > 0 && codes[i] == codes[i - 1]) dp[i] = dp[i - 1] + 1;
    if (dp[i] >= targetRun) {
      out.add(codes.substring(i - targetRun + 1, i + 1));
    }
  }
  return out;
}

