void fn0() {

  final edges = [
    [0, 1, -1],
    [0, 2, 4],
    [1, 2, 3],
    [1, 3, 2],
    [1, 4, 2],
    [3, 2, 5],
    [3, 1, 1],
    [4, 3, -3],
  ];

  final numVertices = 5;
  final source = 0;

  final distances = List<int>.filled(numVertices, 999999999);
  distances[source] = 0;

  final parent = List<int>.filled(numVertices, -1);

  for (int i = 0; i < numVertices - 1; i++) {
    for (final edge in edges) {
      int u = edge[0];
      int v = edge[1];
      int weight = edge[2];

      if (distances[u] != 999999999 && 
          distances[u] + weight < distances[v]) {
        distances[v] = distances[u] + weight;
        parent[v] = u;
      }
    }
  }

  bool hasNegativeCycle = false;
  for (final edge in edges) {
    int u = edge[0];
    int v = edge[1];
    int weight = edge[2];

    if (distances[u] != 999999999 && 
        distances[u] + weight < distances[v]) {
      hasNegativeCycle = true;
      break;
    }
  }

  print('Bellman-Ford Shortest Path Algorithm');
  print('=====================================');

  if (hasNegativeCycle) {
    print('Graph contains negative weight cycle!');
  } else {
    print('Shortest distances from vertex $source:');
    print('');

    for (int i = 0; i < numVertices; i++) {
      if (distances[i] == 999999999) {
        print('Vertex $i: No path');
      } else {
        print('Vertex $i: Distance = ${distances[i]}');

        List<int> path = [];
        int current = i;

        while (current != -1) {
          path.add(current);
          current = parent[current];
        }

        if (path.length > 1) {
          path = path.reversed.toList();
          String pathStr = path.join(' -> ');
          print('  Path: $pathStr');
        }
      }
      print('');
    }
  }

  print('Testing graph with negative cycle:');
  print('===================================');

  final edgesWithCycle = [
    [0, 1, 1],
    [1, 2, -3],
    [2, 0, 1],  
    [0, 3, 2],
    [3, 4, 1],
  ];

  final distances2 = List<int>.filled(numVertices, 999999999);
  distances2[source] = 0;

  for (int i = 0; i < numVertices - 1; i++) {
    for (final edge in edgesWithCycle) {
      int u = edge[0];
      int v = edge[1];
      int weight = edge[2];

      if (distances2[u] != 999999999 && 
          distances2[u] + weight < distances2[v]) {
        distances2[v] = distances2[u] + weight;
      }
    }
  }

  bool hasNegativeCycle2 = false;
  for (final edge in edgesWithCycle) {
    int u = edge[0];
    int v = edge[1];
    int weight = edge[2];

    if (distances2[u] != 999999999 && 
        distances2[u] + weight < distances2[v]) {
      hasNegativeCycle2 = true;
      break;
    }
  }

  if (hasNegativeCycle2) {
    print('Negative weight cycle detected!');
  } else {
    print('No negative weight cycle found.');
  }
}

