List<String> fn0(List<int> bucketMasks, int rotate, int hotCount) {
  var out = <String>[];
  for (var m in bucketMasks) {
    var s = rotate & 7;
    var r = ((m << s) | (m >> (8 - s))) & 255;
    var c = r.toRadixString(2).replaceAll('0', '').length;
    out.add('${c >= hotCount ? 'hot' : 'cold'}:${r & 15}');
  }
  return out;
}

